def _unique_long_ratio(text: str, min_wc: int = 50) -> float:
    words = [w.strip(string.punctuation).lower() for w in text.split()
             if w.strip(string.punctuation)]
    if not words:
        return 0.0
    unique_long = len({w for w in words if len(w) >= 7 and w not in COMMON_LONG_WORDS})
    raw_ratio = unique_long / len(words)
    if len(words) < min_wc:
        return raw_ratio * (len(words) / min_wc)
    return raw_ratio
